contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address caddress, address[] memory tos, uint[] memory v) public payable {
        bool reverted;
        bool ret;
        try c.transfer(from, caddress, tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
        }
        if (tos.length == 0) {
            assert(reverted);
        } else {
            assert(!reverted == false || ret == true);
            assert(!reverted && ret || reverted);
            assert(!reverted || !ret == false);
            if (!reverted) {
                assert(ret);
            } else {
                assert(true);
            }
            assert(!reverted == false || ret);
        }
    }
    receive() external payable {}
}

